import { InputRule, Node, isNodeActive, mergeAttributes } from "@tiptap/core";
import { findWrapping } from "@tiptap/pm/transform";
import { ReactNodeViewRenderer } from "@tiptap/react";

import {
  ALERT_BY_VARIANT,
  alertToVariant,
  findCallout,
  isCalloutVariant,
  toCalloutVariant,
  unwrapCallout,
} from "./utils";
import type { CalloutAttributes } from "./utils";
import { CalloutView } from "./view";

export {
  CALLOUT_VARIANTS,
  isCalloutVariant,
  toCalloutVariant,
  alertToVariant,
  findCallout,
  unwrapCallout,
} from "./utils";
export type { CalloutAttributes, CalloutVariant } from "./utils";

export interface CalloutOptions {
  HTMLAttributes: Record<string, unknown>;
}

declare module "@tiptap/core" {
  interface Commands<ReturnType> {
    callout: {
      setCallout: (attributes?: CalloutAttributes) => ReturnType;
      toggleCallout: (attributes?: CalloutAttributes) => ReturnType;
      unsetCallout: () => ReturnType;
      updateCallout: (attributes: CalloutAttributes) => ReturnType;
    };
  }
}

const ALERT_INPUT = /^>?\s?\[!(\w+)\]\s$/;
const ALERT_BLOCK =
  /^ {0,3}>[ \t]*\[!(\w+)\][ \t]*(?:\n|$)((?: {0,3}>.*(?:\n|$))*)/;
const ALERT_START = /^ {0,3}>[ \t]*\[!\w+\]/m;

export const Callout = Node.create<CalloutOptions>({
  addAttributes() {
    return {
      emoji: {
        default: null,
        parseHTML: (element) => element.dataset.emoji || null,
        renderHTML: (attributes) =>
          attributes.emoji ? { "data-emoji": attributes.emoji } : {},
      },
      variant: {
        default: "info",
        parseHTML: (element) => toCalloutVariant(element.dataset.variant),
        renderHTML: (attributes) => ({ "data-variant": attributes.variant }),
      },
    };
  },
  addCommands() {
    return {
      setCallout:
        (attributes = {}) =>
        ({ commands }) =>
          commands.wrapIn(this.name, attributes),
      toggleCallout:
        (attributes = {}) =>
        ({ commands, state }) =>
          isNodeActive(state, this.type)
            ? commands.unsetCallout()
            : commands.setCallout(attributes),
      unsetCallout:
        () =>
        ({ state, tr, dispatch }) => {
          const callout = findCallout(state.selection, this.name);
          if (!callout) {
            return false;
          }
          if (!dispatch) {
            return true;
          }
          return unwrapCallout(tr, callout.pos, callout.node);
        },
      updateCallout:
        (attributes) =>
        ({ state, tr, dispatch }) => {
          const callout = findCallout(state.selection, this.name);
          if (!callout) {
            return false;
          }
          if (dispatch) {
            tr.setNodeMarkup(callout.pos, undefined, {
              ...callout.node.attrs,
              ...attributes,
            });
          }
          return true;
        },
    };
  },
  addInputRules() {
    return [
      new InputRule({
        find: ALERT_INPUT,
        handler: ({ state, range, match }) => {
          const variant = alertToVariant(match[1]);
          if (!variant) {
            return null;
          }
          const { tr } = state;
          tr.delete(range.from, range.to);
          const $start = tr.doc.resolve(range.from);
          const parentDepth = $start.depth - 1;
          const parent = $start.node(parentDepth);
          if (
            parentDepth > 0 &&
            parent.type.name === "blockquote" &&
            $start.index(parentDepth) === 0
          ) {
            tr.setNodeMarkup($start.before(parentDepth), this.type, {
              variant,
            });
            return;
          }
          const blockRange = $start.blockRange();
          const wrapping =
            blockRange && findWrapping(blockRange, this.type, { variant });
          if (!(blockRange && wrapping)) {
            return null;
          }
          tr.wrap(blockRange, wrapping);
        },
      }),
    ];
  },
  addKeyboardShortcuts() {
    return {
      Enter: () => {
        const { $from, empty } = this.editor.state.selection;
        const depth = $from.depth - 1;
        if (
          !empty ||
          depth < 1 ||
          !$from.parent.isTextblock ||
          $from.parent.content.size > 0 ||
          $from.node(depth).type !== this.type
        ) {
          return false;
        }
        const isLast = $from.index(depth) === $from.node(depth).childCount - 1;
        return isLast
          ? this.editor.commands.lift(this.name)
          : this.editor.commands.splitBlock();
      },
    };
  },
  addNodeView() {
    return ReactNodeViewRenderer(CalloutView);
  },
  addOptions() {
    return { HTMLAttributes: {} };
  },
  content: "block+",
  defining: true,
  group: "block",
  markdownTokenName: "callout",
  markdownTokenizer: {
    level: "block",
    name: "callout",
    start: (src) => src.search(ALERT_START),
    tokenize: (src, _tokens, lexer) => {
      const match = ALERT_BLOCK.exec(src);
      const variant = match && alertToVariant(match[1]);
      if (!(match && variant)) {
        return;
      }
      const body = (match[2] ?? "")
        .split("\n")
        .map((line) => line.replace(/^ {0,3}> ?/, ""))
        .join("\n");
      return {
        raw: match[0],
        tokens: lexer.blockTokens(body),
        type: "callout",
        variant,
      };
    },
  },
  name: "callout",
  parseHTML() {
    return [{ tag: 'div[data-type="callout"]' }];
  },
  parseMarkdown: (token, helpers) => {
    const content = helpers.parseChildren(token.tokens ?? []);
    return helpers.createNode(
      "callout",
      { variant: token.variant },
      content.length > 0 ? content : [{ type: "paragraph" }]
    );
  },
  renderHTML({ HTMLAttributes }) {
    return [
      "div",
      mergeAttributes(
        { "data-type": "callout" },
        this.options.HTMLAttributes,
        HTMLAttributes
      ),
      0,
    ];
  },
  renderMarkdown: (node, helpers) => {
    const variant = isCalloutVariant(node.attrs?.variant)
      ? node.attrs.variant
      : "info";
    const lines = [`> [!${ALERT_BY_VARIANT[variant]}]`];
    for (const [index, child] of (node.content ?? []).entries()) {
      if (index > 0) {
        lines.push(">");
      }
      const text =
        helpers.renderChild?.(child, index) ?? helpers.renderChildren([child]);
      for (const line of text.split("\n")) {
        lines.push(line === "" ? ">" : `> ${line}`);
      }
    }
    return lines.join("\n");
  },
});

"use client";

import type { ReactNodeViewProps } from "@tiptap/react";
import { NodeViewContent, NodeViewWrapper } from "@tiptap/react";
import { useState } from "react";

import { useToolbar } from "../core/context";
import { useEditable } from "../core/editor-state";
import { Button } from "../ui/button";
import { DropdownMenu } from "../ui/dropdown-menu";
import { CalloutIcon, CalloutMenu } from "./menu";
import { toCalloutVariant, unwrapCallout } from "./utils";
import type { CalloutVariant } from "./utils";

export const CalloutView = ({
  editor,
  getPos,
  node,
  updateAttributes,
}: ReactNodeViewProps) => {
  const { labels } = useToolbar();
  const variant = toCalloutVariant(node.attrs.variant);
  const emoji = (node.attrs.emoji as string | null) || null;
  const editable = useEditable(editor);
  const [open, setOpen] = useState(false);

  if (open && !editable) {
    setOpen(false);
  }

  const select = (next: CalloutVariant) => {
    setOpen(false);
    if (editor.isEditable) {
      updateAttributes({ variant: next });
    }
  };

  const resetEmoji = () => {
    setOpen(false);
    if (editor.isEditable) {
      updateAttributes({ emoji: null });
    }
  };

  const remove = () => {
    setOpen(false);
    const pos = getPos();
    if (!editor.isEditable || typeof pos !== "number") {
      return;
    }
    editor
      .chain()
      .focus()
      .command(({ tr }) => unwrapCallout(tr, pos, node))
      .run();
  };

  const icon = <CalloutIcon emoji={emoji} variant={variant} />;

  return (
    <NodeViewWrapper
      className="ext-callout"
      data-type="callout"
      data-variant={variant}
    >
      <div className="ext-callout-icon" contentEditable={false}>
        {editable ? (
          <DropdownMenu
            open={open}
            onOpenChange={setOpen}
            trigger={
              <Button
                className="ext-btn--icon-sm ext-callout-trigger"
                aria-label={labels.calloutType}
              >
                {icon}
              </Button>
            }
          >
            <CalloutMenu
              value={variant}
              onSelect={select}
              onResetEmoji={emoji ? resetEmoji : undefined}
              onRemove={remove}
            />
          </DropdownMenu>
        ) : (
          <span className="ext-callout-trigger" aria-hidden="true">
            {icon}
          </span>
        )}
      </div>
      <NodeViewContent className="ext-callout-content" />
    </NodeViewWrapper>
  );
};

"use client";

import { MessageSquareWarning } from "lucide-react";
import { useState } from "react";

import { useToolbar, useToolbarEditor } from "../core/context";
import { extensionPresent } from "../core/detection";
import {
  shallowEqual,
  useEditable,
  useEditorState,
} from "../core/editor-state";
import type { ToolbarComponentProps } from "../core/types";
import { Button } from "../ui/button";
import { Popover } from "../ui/popover";
import { CalloutMenu } from "./menu";
import { toCalloutVariant } from "./utils";
import type { CalloutVariant } from "./utils";

export const CalloutToolbar = ({
  className,
  editor: editorProp,
}: ToolbarComponentProps) => {
  const { labels } = useToolbar();
  const editor = useToolbarEditor(editorProp);
  const [open, setOpen] = useState(false);
  const editable = useEditable(editor);

  const state = useEditorState(
    editor,
    (edit) => {
      const active = !edit.isDestroyed && edit.isActive("callout");
      return {
        disabled:
          !extensionPresent(edit, "callout") ||
          !(active || edit.can().setCallout()),
        variant: active
          ? toCalloutVariant(edit.getAttributes("callout").variant)
          : null,
      };
    },
    shallowEqual
  ) ?? { disabled: true, variant: null };
  const disabled = state.disabled || !editable;

  if (open && disabled) {
    setOpen(false);
  }

  const select = (variant: CalloutVariant) => {
    setOpen(false);
    if (!editor || disabled || !editor.isEditable) {
      return;
    }
    const chain = editor.chain().focus();
    if (state.variant) {
      chain.updateCallout({ variant }).run();
    } else {
      chain.setCallout({ variant }).run();
    }
  };

  const remove = () => {
    setOpen(false);
    if (editor?.isEditable) {
      editor.chain().focus().unsetCallout().run();
    }
  };

  return (
    <Popover
      open={open}
      onOpenChange={setOpen}
      side="bottom"
      align="start"
      sideOffset={6}
      trigger={
        <Button
          aria-label={labels.callout}
          active={Boolean(state.variant)}
          className={["ext-btn--icon-sm", className].filter(Boolean).join(" ")}
          disabled={disabled}
          tooltip={labels.callout}
        >
          <MessageSquareWarning />
        </Button>
      }
    >
      <CalloutMenu
        value={state.variant}
        onSelect={select}
        onRemove={state.variant ? remove : undefined}
      />
    </Popover>
  );
};

"use client";

import {
  Check,
  Info,
  Lightbulb,
  OctagonAlert,
  SmilePlus,
  StickyNote,
  Trash2,
  TriangleAlert,
} from "lucide-react";
import type { LucideIcon } from "lucide-react";
import { useEffect, useRef } from "react";
import type { KeyboardEvent } from "react";

import { useToolbar } from "../core/context";
import type { ExtensionLabelKey } from "../core/labels";
import { DropdownMenuContent } from "../ui/dropdown-content";
import { DropdownMenuItem } from "../ui/dropdown-item";
import { DropdownMenuSeparator } from "../ui/dropdown-separator";
import type { CalloutVariant } from "./utils";

export const CALLOUT_ICONS: Record<CalloutVariant, LucideIcon> = {
  danger: OctagonAlert,
  info: Info,
  note: StickyNote,
  tip: Lightbulb,
  warning: TriangleAlert,
};

const VARIANT_LABELS: [CalloutVariant, ExtensionLabelKey][] = [
  ["info", "calloutInfo"],
  ["tip", "calloutTip"],
  ["warning", "calloutWarning"],
  ["danger", "calloutDanger"],
  ["note", "calloutNote"],
];

export const CalloutIcon = ({
  emoji,
  variant,
}: {
  emoji?: string | null;
  variant: CalloutVariant;
}) => {
  if (emoji) {
    return <span className="ext-callout-emoji">{emoji}</span>;
  }
  const Icon = CALLOUT_ICONS[variant];
  return <Icon />;
};

export interface CalloutMenuProps {
  onRemove?: () => void;
  onResetEmoji?: () => void;
  onSelect: (variant: CalloutVariant) => void;
  value?: CalloutVariant | null;
}

export const CalloutMenu = ({
  onRemove,
  onResetEmoji,
  onSelect,
  value,
}: CalloutMenuProps) => {
  const { labels } = useToolbar();
  const listRef = useRef<HTMLDivElement>(null);

  const items = () => [
    ...(listRef.current?.querySelectorAll<HTMLElement>(
      ":scope > [data-dropdown-item]"
    ) ?? []),
  ];

  useEffect(() => {
    const trigger =
      document.activeElement instanceof HTMLElement
        ? document.activeElement
        : null;
    let escaped = false;
    const onEscape = (event: globalThis.KeyboardEvent) => {
      if (event.key === "Escape") {
        escaped = true;
      }
    };
    document.addEventListener("keydown", onEscape, true);
    return () => {
      document.removeEventListener("keydown", onEscape, true);
      if (escaped && trigger?.isConnected) {
        trigger.focus();
      }
    };
  }, []);

  useEffect(() => {
    const all = items();
    const index = Math.max(
      0,
      VARIANT_LABELS.findIndex(([variant]) => variant === value)
    );
    all[index]?.focus();
  }, [value]);

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key !== "ArrowDown" && event.key !== "ArrowUp") {
      return;
    }
    event.preventDefault();
    const all = items();
    const current = all.indexOf(document.activeElement as HTMLElement);
    const delta = event.key === "ArrowDown" ? 1 : -1;
    all[(current + delta + all.length) % all.length]?.focus();
  };

  return (
    <DropdownMenuContent
      ref={listRef}
      aria-label={labels.callout}
      onKeyDown={onKeyDown}
      style={{ minWidth: "10rem" }}
    >
      {VARIANT_LABELS.map(([variant, label]) => {
        const Icon = CALLOUT_ICONS[variant];
        return (
          <DropdownMenuItem
            key={variant}
            role="menuitemradio"
            aria-checked={variant === value}
            className="ext-callout-menu-item"
            data-variant={variant}
            onClick={() => onSelect(variant)}
          >
            <Icon />
            <span>{labels[label]}</span>
            {variant === value && <Check className="ext-callout-check" />}
          </DropdownMenuItem>
        );
      })}
      {(onResetEmoji || onRemove) && <DropdownMenuSeparator />}
      {onResetEmoji && (
        <DropdownMenuItem onClick={onResetEmoji}>
          <SmilePlus />
          <span>{labels.resetCalloutIcon}</span>
        </DropdownMenuItem>
      )}
      {onRemove && (
        <DropdownMenuItem danger onClick={onRemove}>
          <Trash2 />
          <span>{labels.removeCallout}</span>
        </DropdownMenuItem>
      )}
    </DropdownMenuContent>
  );
};

import { findParentNode } from "@tiptap/core";
import type { Node as PMNode } from "@tiptap/pm/model";
import { NodeSelection } from "@tiptap/pm/state";
import type { Selection, Transaction } from "@tiptap/pm/state";
import { liftTarget } from "@tiptap/pm/transform";

export const CALLOUT_VARIANTS = [
  "info",
  "tip",
  "warning",
  "danger",
  "note",
] as const;

export type CalloutVariant = (typeof CALLOUT_VARIANTS)[number];

export interface CalloutAttributes {
  emoji?: string | null;
  variant?: CalloutVariant;
}

export const ALERT_BY_VARIANT: Record<CalloutVariant, string> = {
  danger: "CAUTION",
  info: "IMPORTANT",
  note: "NOTE",
  tip: "TIP",
  warning: "WARNING",
};

export const VARIANT_BY_ALERT: Record<string, CalloutVariant> = {
  caution: "danger",
  danger: "danger",
  important: "info",
  info: "info",
  note: "note",
  tip: "tip",
  warning: "warning",
};

export const isCalloutVariant = (value: unknown): value is CalloutVariant =>
  CALLOUT_VARIANTS.includes(value as CalloutVariant);

export const alertToVariant = (value: unknown): CalloutVariant | null => {
  const key = String(value).toLowerCase();
  return Object.hasOwn(VARIANT_BY_ALERT, key)
    ? (VARIANT_BY_ALERT[key] ?? null)
    : null;
};

export const toCalloutVariant = (value: unknown): CalloutVariant =>
  alertToVariant(value) ?? "info";

export const findCallout = (selection: Selection, name: string) => {
  if (
    selection instanceof NodeSelection &&
    selection.node.type.name === name
  ) {
    return { node: selection.node, pos: selection.from };
  }
  return findParentNode((node) => node.type.name === name)(selection) ?? null;
};

export const unwrapCallout = (tr: Transaction, pos: number, node: PMNode) => {
  const range = tr.doc
    .resolve(pos + 1)
    .blockRange(tr.doc.resolve(pos + node.nodeSize - 1));
  const target = range && liftTarget(range);
  if (!range || target === null || target === undefined) {
    return false;
  }
  tr.lift(range, target);
  return true;
};

"use client";

import { useCallback, useEffect, useLayoutEffect, useRef } from "react";
import type { CSSProperties, ReactNode, ReactPortal } from "react";
import { createPortal } from "react-dom";

export type FloatingSide = "bottom" | "top" | "left" | "right";
export type FloatingAlign = "start" | "center" | "end";

export interface UseFloatingOptions {
  align?: FloatingAlign;
  onOpenChange?: (open: boolean) => void;
  open: boolean;
  side?: FloatingSide;
  sideOffset?: number;
}

const clamp = (value: number, max: number): number =>
  Math.max(8, Math.min(value, Math.max(8, max)));

export const useFloating = ({
  align = "center",
  onOpenChange,
  open,
  side = "bottom",
  sideOffset = 4,
}: UseFloatingOptions) => {
  const triggerRef = useRef<HTMLElement | null>(null);
  const contentRef = useRef<HTMLDivElement | null>(null);

  const close = useCallback(() => {
    onOpenChange?.(false);
  }, [onOpenChange]);

  const applyPosition = useCallback(() => {
    const trigger = triggerRef.current;
    const content = contentRef.current;
    if (!(trigger instanceof HTMLElement) || !content) {
      return;
    }
    const rect = trigger.getBoundingClientRect();
    const width = content.offsetWidth;
    const height = content.offsetHeight;

    let left: number | undefined;
    let top: number | undefined;
    let right: number | undefined;
    let bottom: number | undefined;
    const translate: string[] = [];

    if (side === "bottom" || side === "top") {
      if (side === "bottom") {
        top = clamp(rect.bottom + sideOffset, window.innerHeight - height);
      } else {
        bottom = window.innerHeight - rect.top + sideOffset;
      }
      if (align === "center") {
        left = clamp(rect.left + rect.width / 2, window.innerWidth - width);
        translate.push("translateX(-50%)");
      } else if (align === "end") {
        right = clamp(
          window.innerWidth - rect.right,
          window.innerWidth - width
        );
      } else {
        left = clamp(rect.left, window.innerWidth - width);
      }
    } else {
      if (side === "right") {
        left = clamp(rect.right + sideOffset, window.innerWidth - width);
      } else {
        right = window.innerWidth - rect.left + sideOffset;
      }
      if (align === "center") {
        top = clamp(rect.top + rect.height / 2, window.innerHeight - height);
        translate.push("translateY(-50%)");
      } else if (align === "end") {
        bottom = window.innerHeight - rect.bottom;
      } else {
        top = clamp(rect.top, window.innerHeight - height);
      }
    }

    content.style.left = left === undefined ? "" : `${left}px`;
    content.style.top = top === undefined ? "" : `${top}px`;
    content.style.right = right === undefined ? "" : `${right}px`;
    content.style.bottom = bottom === undefined ? "" : `${bottom}px`;
    content.style.transform = translate.join(" ");
  }, [align, side, sideOffset]);

  useLayoutEffect(() => {
    if (!open) {
      return;
    }
    applyPosition();
    const handleScroll = () => {
      applyPosition();
    };
    const handleResize = () => {
      applyPosition();
    };
    window.addEventListener("scroll", handleScroll, true);
    window.addEventListener("resize", handleResize);
    // The trigger can also move without a scroll or resize — a table grip
    // shifts when its row or column is added or deleted. Follow it per frame
    // so the open menu never detaches from its trigger.
    let frame: number;
    const follow = () => {
      applyPosition();
      frame = requestAnimationFrame(follow);
    };
    frame = requestAnimationFrame(follow);
    return () => {
      cancelAnimationFrame(frame);
      window.removeEventListener("scroll", handleScroll, true);
      window.removeEventListener("resize", handleResize);
    };
  }, [applyPosition, open]);

  useEffect(() => {
    if (!open) {
      return;
    }
    const handlePointerDown = (e: PointerEvent) => {
      const target = e.target as HTMLElement | null;
      if (
        target &&
        (triggerRef.current?.contains(target) ||
          contentRef.current?.contains(target))
      ) {
        return;
      }
      close();
    };
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        close();
      }
    };
    document.addEventListener("pointerdown", handlePointerDown, true);
    document.addEventListener("keydown", handleKeyDown, true);
    return () => {
      document.removeEventListener("pointerdown", handlePointerDown, true);
      document.removeEventListener("keydown", handleKeyDown, true);
    };
  }, [close, open]);

  const content = (children: ReactNode): null | ReactPortal =>
    open
      ? createPortal(
          <div
            ref={contentRef}
            data-ext-floating
            style={{ position: "fixed", zIndex: 60 } as CSSProperties}
          >
            {children}
          </div>,
          document.body
        )
      : null;

  return { content, triggerRef };
};

