.ext-separator--horizontal {
  height: 1px;
  margin: 0.25rem 0;
}

.ext-separator--vertical {
  width: 1px;
  height: 1rem;
  align-self: center;
  margin: 0 0.25rem;
}

/* ── Input ── */
.ext-input {
  width: 100%;
  height: 2rem;
  padding: 0 0.625rem;
  border: 1px solid var(--border);
  border-radius: calc(var(--radius) - 2px);
  background: var(--background);
  color: var(--foreground);
  font-size: 0.8125rem;
  font-family: inherit;
  outline: none;
  transition:
    border-color 150ms ease-out,
    box-shadow 150ms ease-out;
}

.ext-input::placeholder {
  color: var(--muted-foreground);
}

.ext-input:focus-visible {
  border-color: var(--ring);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--ring) 30%, transparent);
}

/* ── Tabs ── */
.ext-tabs {
  display: flex;
  flex-direction: column;
}

.ext-tabs-list {
  display: flex;
  gap: 0.125rem;
  width: fit-content;
  padding: 0.25rem;
  border-radius: calc(var(--radius) - 4px);
  background: var(--muted);
}

.ext-tabs-trigger {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.25rem 0.625rem;
  border: none;
  border-radius: calc(var(--radius) - 6px);
  background: transparent;
  color: var(--muted-foreground);
  font-size: 0.8125rem;
  font-family: inherit;
  white-space: nowrap;
  cursor: pointer;
  transition:
    background-color 150ms ease-out,
    color 150ms ease-out;
}

.ext-tabs-trigger > svg {
  width: 1rem;
  height: 1rem;
  flex-shrink: 0;
}

.ext-tabs-trigger:hover,
.ext-tabs-trigger:focus-visible {
  color: var(--foreground);
  outline: none;
}

.ext-tabs-trigger--active {
  background: var(--background);
  color: var(--foreground);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.06);
}

.ext-tabs-content {
  padding-top: 0.5rem;
}
